import path from 'node:path'
import { drizzle } from 'drizzle-orm/node-postgres'
import { migrate } from 'drizzle-orm/node-postgres/migrator'
import pg from 'pg'
import * as schema from './schema.ts'

/** One pool for the whole API: Drizzle queries and the session store share it. */
export function connect(databaseUrl: string) {
  const pool = new pg.Pool({ connectionString: databaseUrl })
  const db = drizzle(pool, { schema })
  return { pool, db }
}

export type Db = ReturnType<typeof connect>['db']

/** Applies the SQL migrations generated by drizzle-kit (api/drizzle/). */
export function runMigrations(db: Db): Promise<void> {
  return migrate(db, { migrationsFolder: path.join(import.meta.dirname, '../../drizzle') })
}
